import openpyxl, re
wb = openpyxl.load_workbook('seed_collection_0057_embedded_hardcodes_2530_input.xlsx', data_only=False)
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for c in row:
            if c.data_type == 'f' or (isinstance(c.value, str) and c.value.startswith('=')):
                v=c.value
                if re.search(r'\d', v):
                    print(f'{ws.title}!{c.coordinate}: {v}')
